import * as RNFS from '@dr.pogodin/react-native-fs';

// Only names generated by our private-copy/export helpers, including Realm's
// sidecars. Never inspect the document provider, Drive, photos or live databases.
const temporaryBackup = /^(?:backup-\d+-\d+\.(?:json|realm)|(?:bebbo-import|drive-backup)-\d+-\d+\.realm)(?:\.lock|\.note|\.management)?$/;

/** Run before the import/export UI mounts: finally blocks cannot survive a process kill. */
export async function cleanupAbandonedBackupFiles(): Promise<{removed: number; failed: number}> {
  const entries = await RNFS.readDir(RNFS.CachesDirectoryPath);
  let removed = 0, failed = 0;
  for (const entry of entries) {
    if (!temporaryBackup.test(entry.name)) continue;
    if (!entry.isFile() && !(entry.name.endsWith('.realm.management') && entry.isDirectory())) continue;
    try {
      // Construct from the constrained basename, not a provider-returned path.
      await RNFS.unlink(`${RNFS.CachesDirectoryPath}/${entry.name}`);
      removed++;
    } catch { failed++; }
  }
  return {removed, failed};
}
